<script>
const DATA = [
  { model: "GPT-4o",          family: "GPT",    scores: [92, 89, 85, 91, 88, 90, 42, 93], top: true  },
  { model: "GPT-4o-mini",     family: "GPT",    scores: [74, 76, 68, 80, 72, 82, 78, 79], top: false },
  { model: "Claude 3.5 Sonnet", family:"Claude", scores: [94, 93, 82, 93, 85, 95, 38, 90], top: true  },
  { model: "Claude 3 Haiku",  family: "Claude", scores: [68, 70, 60, 76, 65, 78, 91, 72], top: false },
  { model: "Gemini 1.5 Pro",  family: "Gemini", scores: [88, 82, 72, 87, 95, 86, 45, 91], top: true  },
  { model: "Gemini 1.5 Flash",family: "Gemini", scores: [70, 68, 58, 75, 82, 74, 88, 74], top: false },
  { model: "LLaMA 3.1 405B", family: "LLaMA",  scores: [86, 84, 90, 84, 45, 80, 35, 88], top: false },
  { model: "LLaMA 3.1 70B",  family: "LLaMA",  scores: [76, 74, 78, 75, 40, 72, 62, 76], top: false },
  { model: "Qwen2.5 72B",    family: "Qwen",   scores: [83, 86, 92, 82, 52, 81, 48, 85], top: false },
  { model: "Qwen2.5 7B",     family: "Qwen",   scores: [58, 62, 70, 64, 38, 60, 93, 60], top: false },
];

const DIMS = [
  "Reasoning",
  "Code\nGeneration",
  "Math /\nQuantitative",
  "Language\nUnderstanding",
  "Multimodal\nUnderstanding",
  "Instruction\nFollowing",
  "Inference\nSpeed",
  "Knowledge\nRecall"
];

const FAMILY_COLORS = {
  GPT:    "#4a9eff",
  Claude: "#b87fff",
  Gemini: "#3ecf8e",
  LLaMA:  "#f5a623",
  Qwen:   "#ff6b6b",
};

const canvas = document.getElementById("chart");
const dpr = window.devicePixelRatio || 1;

function hexToRgb(hex) {
  const r = parseInt(hex.slice(1,3),16);
  const g = parseInt(hex.slice(3,5),16);
  const b = parseInt(hex.slice(5,7),16);
  return {r, g, b};
}

function draw() {
  const W = canvas.parentElement.clientWidth - 80; // account for parent padding
  const H = 520;
  canvas.width = W * dpr;
  canvas.height = H * dpr;
  canvas.style.width = W + "px";
  canvas.style.height = H + "px";

  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);

  const marginTop = 20;
  const marginBottom = 72;  // space for axis labels
  const marginLeft = 30;
  const marginRight = 30;

  const nDims = DIMS.length;
  const axisSpacing = (W - marginLeft - marginRight) / (nDims - 1);
  const axisTop = marginTop;
  const axisBottom = H - marginBottom;
  const axisHeight = axisBottom - axisTop;

  function xForDim(i) { return marginLeft + i * axisSpacing; }
  function yForScore(score) { return axisBottom - (score / 100) * axisHeight; }

  // Draw subtle background grid zones
  for (let i = 0; i < nDims; i++) {
    const x = xForDim(i);
    // Highlight axis band
    ctx.fillStyle = "rgba(255,255,255,0.025)";
    ctx.fillRect(x - 18, axisTop, 36, axisHeight);
  }

  // Draw crossing highlight band between Reasoning (0) and Inference Speed (6)
  const xR = xForDim(0);
  const xS = xForDim(6);
  const grad = ctx.createLinearGradient(xR, 0, xS, 0);
  grad.addColorStop(0, "rgba(255,255,100,0.0)");
  grad.addColorStop(0.5, "rgba(255,255,100,0.04)");
  grad.addColorStop(1, "rgba(255,255,100,0.0)");
  ctx.fillStyle = grad;
  ctx.fillRect(xR, axisTop, xS - xR, axisHeight);

  // Draw gridlines (score ticks)
  [0, 25, 50, 75, 100].forEach(v => {
    const y = yForScore(v);
    ctx.beginPath();
    ctx.moveTo(marginLeft, y);
    ctx.lineTo(W - marginRight, y);
    ctx.strokeStyle = "rgba(255,255,255,0.05)";
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 5]);
    ctx.stroke();
    ctx.setLineDash([]);

    // Tick labels on leftmost axis
    ctx.fillStyle = "rgba(255,255,255,0.22)";
    ctx.font = `10px 'IBM Plex Mono', monospace`;
    ctx.textAlign = "right";
    ctx.fillText(v, marginLeft - 6, y + 3.5);
  });

  // Draw polylines — non-top first (dimmer), then top models on top
  const drawOrder = [...DATA].sort((a, b) => (a.top ? 1 : -1) - (b.top ? 1 : -1));

  drawOrder.forEach(d => {
    const color = FAMILY_COLORS[d.family];
    const rgb = hexToRgb(color);
    const alpha = d.top ? 0.88 : 0.34;
    const lw = d.top ? 2.8 : 1.2;

    ctx.beginPath();
    d.scores.forEach((score, i) => {
      const x = xForDim(i);
      const y = yForScore(score);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });

    ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${alpha})`;
    ctx.lineWidth = lw;
    ctx.lineJoin = "round";
    ctx.shadowBlur = d.top ? 8 : 0;
    ctx.shadowColor = d.top ? color : "transparent";
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw dots at each axis intersection
    d.scores.forEach((score, i) => {
      const x = xForDim(i);
      const y = yForScore(score);
      ctx.beginPath();
      ctx.arc(x, y, d.top ? 4.2 : 2.5, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${d.top ? 0.95 : 0.5})`;
      ctx.fill();
    });
  });

  // Draw axis lines
  for (let i = 0; i < nDims; i++) {
    const x = xForDim(i);
    ctx.beginPath();
    ctx.moveTo(x, axisTop);
    ctx.lineTo(x, axisBottom);
    ctx.strokeStyle = "rgba(255,255,255,0.30)";
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Tick marks
    [0, 25, 50, 75, 100].forEach(v => {
      const y = yForScore(v);
      ctx.beginPath();
      ctx.moveTo(x - 4, y);
      ctx.lineTo(x + 4, y);
      ctx.strokeStyle = "rgba(255,255,255,0.45)";
      ctx.lineWidth = 1;
      ctx.stroke();
    });
  }

  // Draw axis labels (multi-line handled manually)
  ctx.textAlign = "center";
  DIMS.forEach((dim, i) => {
    const x = xForDim(i);
    const lines = dim.split("\n");
    const lineH = 14;
    const totalH = lines.length * lineH;
    const startY = axisBottom + 14;

    // Highlight special axes
    const isReasoningOrSpeed = (i === 0 || i === 6);
    const isMultimodalOrMath = (i === 2 || i === 4);

    lines.forEach((line, li) => {
      ctx.fillStyle = isReasoningOrSpeed
        ? "rgba(255,255,160,0.85)"
        : isMultimodalOrMath
          ? "rgba(130,220,180,0.85)"
          : "rgba(230,237,243,0.65)";
      ctx.font = `${isReasoningOrSpeed || isMultimodalOrMath ? "600" : "500"} 11px 'IBM Plex Sans', sans-serif`;
      ctx.fillText(line, x, startY + li * lineH);
    });
  });

  // Model name labels at the right end for top models
  const rightX = xForDim(nDims - 1);
  DATA.filter(d => d.top).forEach(d => {
    const y = yForScore(d.scores[nDims - 1]);
    const color = FAMILY_COLORS[d.family];
    const rgb = hexToRgb(color);
    ctx.font = `500 10.5px 'IBM Plex Sans', sans-serif`;
    ctx.textAlign = "left";
    ctx.fillStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},0.92)`;
    ctx.fillText(d.model, rightX + 8, y + 4);
  });

  // Arrow annotation for reasoning-speed tradeoff
  ctx.save();
  const arrowY = yForScore(50) - 30;
  const arrowX1 = xForDim(0) + 12;
  const arrowX2 = xForDim(6) - 12;
  ctx.beginPath();
  ctx.moveTo(arrowX1, arrowY);
  ctx.lineTo(arrowX2, arrowY);
  ctx.strokeStyle = "rgba(255,255,160,0.18)";
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();
}

draw();
window.addEventListener("resize", draw);
</script>

</body>
</html>
